import{_ as o,C as r,o as a,c as l,j as e,a as s,b as d,w as i,E as c,a2 as g,a3 as p}from"./chunks/framework.pb1iZPmZ.js";const b=JSON.parse('{"title":"Architectural Design Decisions Log","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/decisions.md","filePath":"system-design/decisions.md"}'),h={name:"system-design/decisions.md"};function f(y,t,m,u,x,S){const n=r("Mermaid");return a(),l("div",null,[t[1]||(t[1]=e("h1",{id:"architectural-design-decisions-log",tabindex:"-1"},[s("Architectural Design Decisions Log "),e("a",{class:"header-anchor",href:"#architectural-design-decisions-log","aria-label":'Permalink to "Architectural Design Decisions Log"'},"​")],-1)),t[2]||(t[2]=e("p",null,"This ledger records every major architectural and implementation decision made in the Sachidanand Member Access Portal, capturing the alternatives considered, the deciding factors, the accepted trade-offs, and the conditions under which each decision should be revisited.",-1)),(a(),d(g,null,{default:i(()=>[c(n,{id:"mermaid-6",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Decisions%5B%22Architectural%20Decisions%20Log%22%5D%20--%3E%20D_DB%5B%22Database%3A%20MongoDB%22%5D%0A%20%20%20%20Decisions%20--%3E%20D_Auth%5B%22Auth%3A%20Stateful%20Sessions%20via%20connect-mongo%22%5D%0A%20%20%20%20Decisions%20--%3E%20D_FW%5B%22Backend%3A%20Express%205%22%5D%0A%20%20%20%20Decisions%20--%3E%20D_UI%5B%22Frontend%3A%20Vanilla%20JS%20%2B%20CSS%20Glassmorphism%22%5D%0A%20%20%20%20Decisions%20--%3E%20D_SSR%5B%22View%20Engine%3A%20EJS%22%5D%0A"})]),fallback:i(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=p('<hr><h2 id="_1-master-decisions-ledger" tabindex="-1">1. Master Decisions Ledger <a class="header-anchor" href="#_1-master-decisions-ledger" aria-label="Permalink to &quot;1. Master Decisions Ledger&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Decision Area</th><th style="text-align:left;">Chosen Option</th><th style="text-align:left;">Alternatives Considered</th><th style="text-align:left;">Deciding Factors</th><th style="text-align:left;">Trade-off Accepted</th><th style="text-align:left;">Revisit When</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Primary Database</strong></td><td style="text-align:left;"><strong>MongoDB with Mongoose ODM</strong> ([<code>app.js:5</code>](file:///Users/avishjain/avishjain9-repos/54-login-auth-portal/app.js#L5))</td><td style="text-align:left;">PostgreSQL, MySQL, SQLite, Firebase, DynamoDB</td><td style="text-align:left;">Natural JSON document mapping; allows single database to store both employee data and session states via <code>connect-mongo</code>.</td><td style="text-align:left;">Lack of database-enforced relational foreign key constraints and ACID multi-table joins.</td><td style="text-align:left;">Hospital data expands to complex multi-table relational healthcare records (prescriptions, insurance billing, patient charts).</td></tr><tr><td style="text-align:left;"><strong>Authentication Strategy</strong></td><td style="text-align:left;"><strong>Stateful Server Sessions (<code>connect-mongo</code>)</strong> ([<code>app.js:34</code>](file:///Users/avishjain/avishjain9-repos/54-login-auth-portal/app.js#L34))</td><td style="text-align:left;">Stateless JWT, Redis Sessions, MemoryStore, OAuth2</td><td style="text-align:left;">Instant session revocation is mandatory on shared hospital workstations; JWTs cannot be revoked immediately on logout without maintaining a distributed blacklist.</td><td style="text-align:left;">Requires a database read on authenticated requests; slightly higher write latency than in-memory Redis.</td><td style="text-align:left;">Active concurrent user sessions exceed 50,000, at which point Redis should be introduced as a dedicated session cache.</td></tr><tr><td style="text-align:left;"><strong>Backend Framework</strong></td><td style="text-align:left;"><strong>Express.js v5.1.0</strong> ([<code>app.js:1</code>](file:///Users/avishjain/avishjain9-repos/54-login-auth-portal/app.js#L1))</td><td style="text-align:left;">NestJS, Fastify, Koa, Django, Spring Boot</td><td style="text-align:left;">Lightweight, unopinionated, massive ecosystem support, and native Promise-based asynchronous error handling in Express 5.</td><td style="text-align:left;">No built-in architectural enforcement or dependency injection container.</td><td style="text-align:left;">Engineering team grows past 15 backend developers requiring strict TypeScript interfaces and auto-generated Swagger OpenAPI docs.</td></tr><tr><td style="text-align:left;"><strong>Frontend Architecture</strong></td><td style="text-align:left;"><strong>Vanilla JavaScript + Pure CSS Glassmorphism</strong> ([<code>login.html:1</code>](file:///Users/avishjain/avishjain9-repos/54-login-auth-portal/login.html#L1))</td><td style="text-align:left;">React SPA, Vue.js, Next.js, Three.js, TailwindCSS</td><td style="text-align:left;">Instantaneous First Contentful Paint (&lt;150ms); eliminates 300KB bundle overhead and client-side hydration delays on low-spec hospital terminals.</td><td style="text-align:left;">No declarative two-way data binding for complex multi-step forms.</td><td style="text-align:left;">The dashboard evolves into a complex clinical Electronic Health Record (EHR) interface with interactive charts and dynamic widgets.</td></tr><tr><td style="text-align:left;"><strong>Templating Engine</strong></td><td style="text-align:left;"><strong>EJS (Embedded JavaScript)</strong> ([<code>app.js:38</code>](file:///Users/avishjain/avishjain9-repos/54-login-auth-portal/app.js#L38))</td><td style="text-align:left;">Pug, Handlebars, Mustache</td><td style="text-align:left;">Direct JavaScript syntax familiarity (<code>&lt;%= username %&gt;</code>); zero compilation learning curve for team members.</td><td style="text-align:left;">Less concise syntax than Pug&#39;s indentation-based markup.</td><td style="text-align:left;">Switching to a unified frontend component framework (e.g. Next.js / React SSR).</td></tr><tr><td style="text-align:left;"><strong>Form Data Transport</strong></td><td style="text-align:left;"><strong>URL-Encoded Forms (<code>body-parser</code>)</strong> ([<code>app.js:27</code>](file:///Users/avishjain/avishjain9-repos/54-login-auth-portal/app.js#L27))</td><td style="text-align:left;">JSON REST Payloads (<code>application/json</code>), GraphQL</td><td style="text-align:left;">Works natively with browser HTML <code>&lt;form&gt;</code> submissions without requiring client-side JavaScript fetch wrappers.</td><td style="text-align:left;">Limits response flexibility; errors require redirects or inline scripts rather than structured JSON error payloads.</td><td style="text-align:left;">Building mobile apps (iOS/Android) or external third-party partner integrations requiring RESTful JSON endpoints.</td></tr><tr><td style="text-align:left;"><strong>Session Invalidation</strong></td><td style="text-align:left;"><strong>HTTP POST <code>/logout</code></strong> ([<code>app.js:119</code>](file:///Users/avishjain/avishjain9-repos/54-login-auth-portal/app.js#L119))</td><td style="text-align:left;">HTTP GET <code>/logout</code></td><td style="text-align:left;">Complies with REST guidelines; protects against CSRF logout attacks and aggressive browser link pre-fetching.</td><td style="text-align:left;">Requires form element or JavaScript POST invocation rather than a simple hyperlink <code>&lt;a&gt;</code>.</td><td style="text-align:left;">Never (POST or DELETE is always mandatory for state-mutating session revocation).</td></tr><tr><td style="text-align:left;"><strong>3D Card Parallax Engine</strong></td><td style="text-align:left;"><strong>GPU CSS Transforms on <code>mousemove</code></strong> ([<code>login.html:461</code>](file:///Users/avishjain/avishjain9-repos/54-login-auth-portal/login.html#L461))</td><td style="text-align:left;">Three.js WebGL canvas, GSAP library</td><td style="text-align:left;">Native GPU compositing achieves 60 FPS with zero external JavaScript dependencies or WebGL overhead.</td><td style="text-align:left;">Mouse tracking must be manually disabled on mobile viewports (&lt;768px) to avoid touch gesture conflicts.</td><td style="text-align:left;">Complex 3D particle physics or custom 3D mesh rendering is required.</td></tr><tr><td style="text-align:left;"><strong>Password Storage (Current)</strong></td><td style="text-align:left;"><strong>Plaintext Prototype Storage</strong> ([<code>app.js:20</code>](file:///Users/avishjain/avishjain9-repos/54-login-auth-portal/app.js#L20))</td><td style="text-align:left;">Bcrypt, Argon2id, PBKDF2</td><td style="text-align:left;">Permitted rapid prototype scaffolding and verification during initial repository setup [CONFIRM WITH DEVELOPER].</td><td style="text-align:left;">Complete absence of cryptographic security; catastrophic liability in production.</td><td style="text-align:left;"><strong>Immediately prior to staging or production deployment</strong> (Upgrade to Argon2id / Bcrypt).</td></tr></tbody></table>',3))])}const D=o(h,[["render",f]]);export{b as __pageData,D as default};
